Use `pg` (node-postgres) with `Pool`:

```js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // Pool sizing
  max: 20,                    // max connections
  min: 2,                     // keep alive
  idleTimeoutMillis: 30000,   // close idle after 30s
  connectionTimeoutMillis: 5000, // fail if can't connect in 5s
  // SSL for prod
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: true } : false,
});

// Surface misconfiguration early
pool.on('error', (err, client) => {
  console.error('Idle client error:', err);
  process.exit(-1); // or alert + graceful shutdown
});
```

Query with error handling:

```js
async function query(text, params) {
  const start = Date.now();
  const client = await pool.connect(); // throws if connectionTimeoutMillis exceeded
  try {
    const res = await client.query(text, params);
    console.log('query duration:', Date.now() - start, 'ms');
    return res;
  } catch (err) {
    // err.code = Postgres error code (e.g. '23505' = unique violation)
    throw err;
  } finally {
    client.release(); // always return to pool
  }
}

// Graceful shutdown
process.on('SIGTERM', async () => {
  await pool.end();
  process.exit(0);
});
```

Transaction wrapper:

```js
async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Usage
await withTransaction(async (client) => {
  await client.query('INSERT INTO orders ...', [...]);
  await client.query('UPDATE inventory ...', [...]);
});
```

Key points:
- `max: 20` — match DB `max_connections` minus headroom for other apps
- `connectionTimeoutMillis` — prevents hung requests when pool exhausted
- `finally { client.release() }` — leak = pool starvation
- `pool.on('error')` — catches errors on idle clients (network blip, DB restart)
